:"payment_tasks_pkey","table":"payment_tasks","schema":"public","definition":"CREATE UNIQUE INDEX payment_tasks_pkey ON public.payment_tasks USING btree (id)"},{"index":"payment_tasks_protection_idx","table":"payment_tasks","schema":"public","definition":"CREATE INDEX payment_tasks_protection_idx ON public.payment_tasks USING btree (protection_id)"},{"index":"payment_tasks_status_idx","table":"payment_tasks","schema":"public","definition":"CREATE INDEX payment_tasks_status_idx ON public.payment_tasks USING btree (status)"},{"index":"protection_plans_pkey","table":"protection_plans","schema":"public","definition":"CREATE UNIQUE INDEX protection_plans_pkey ON public.protection_plans USING btree (id)"},{"index":"protection_plans_provider_idx","table":"protection_plans","schema":"public","definition":"CREATE INDEX protection_plans_provider_idx ON public.protection_plans USING btree (provider_id)"},{"index":"protection_requests_created_idx","table":"protection_requests","schema":"public","definition":"CREATE INDEX protection_requests_created_idx ON public.protection_requests USING btree (created_at DESC)"},{"index":"protection_requests_customer_idx","table":"protection_requests","schema":"public","definition":"CREATE INDEX protection_requests_customer_idx ON public.protection_requests USING btree (customer_id)"},{"index":"protection_requests_number_idx","table":"protection_requests","schema":"public","definition":"CREATE INDEX protection_requests_number_idx ON public.protection_requests USING btree (customer_number_id)"},{"index":"protection_requests_one_pending_per_number","table":"protection_requests","schema":"public","definition":"CREATE UNIQUE INDEX protection_requests_one_pending_per_number ON public.protection_requests USING btree (customer_number_id) WHERE (status = 'pending'::protection_request_status)"},{"index":"protection_requests_pkey","table":"protection_requests","schema":"public","definition":"CREATE UNIQUE INDEX protection_requests_pkey ON public.protection_requests USING btree (id)"},{"index":"protection_requests_status_idx","table":"protection_requests","schema":"public","definition":"CREATE INDEX protection_requests_status_idx ON public.protection_requests USING btree (status)"},{"index":"protections_created_from_request_id_key","table":"protections","schema":"public","definition":"CREATE UNIQUE INDEX protections_created_from_request_id_key ON public.protections USING btree (created_from_request_id)"},{"index":"protections_customer_idx","table":"protections","schema":"public","definition":"CREATE INDEX protections_customer_idx ON public.protections USING btree (customer_id)"},{"index":"protections_end_date_idx","table":"protections","schema":"public","definition":"CREATE INDEX protections_end_date_idx ON public.protections USING btree (end_date)"},{"index":"protections_no_overlapping_active","table":"protections","schema":"public","definition":"CREATE INDEX protections_no_overlapping_active ON public.protections USING gist (customer_number_id, daterange(start_date, (end_date + 1), '[)'::text)) WHERE (status = 'active'::protection_status)"},{"index":"protections_number_idx","table":"protections","schema":"public","definition":"CREATE INDEX protections_number_idx ON public.protections USING btree (customer_number_id)"},{"index":"protections_pkey","table":"protections","schema":"public","definition":"CREATE UNIQUE INDEX protections_pkey ON public.protections USING btree (id)"},{"index":"protections_status_idx","table":"protections","schema":"public","definition":"CREATE INDEX protections_status_idx ON public.protections USING btree (status)"},{"index":"system_settings_pkey","table":"system_settings","schema":"public","definition":"CREATE UNIQUE INDEX system_settings_pkey ON public.system_settings USING btree (id)"},{"index":"task_settings_pkey","table":"task_settings","schema":"public","definition":"CREATE UNIQUE INDEX task_settings_pkey ON public.task_settings USING btree (id)"},{"index":"task_settings_provider_id_key","table":"task_settings","schema":"public","definition":"CREATE UNIQUE INDEX task_settings_provider_id_key ON public.task_settings USING btree (provider_id)"},{"index":"telecom_prefixes_active_prefix_unique","table":"telecom_prefixes","schema":"public","definition":"CREATE UNIQUE INDEX telecom_prefixes_active_prefix_unique ON public.telecom_prefixes USING btree (prefix) WHERE (is_active = true)"},{"index":"telecom_prefixes_pkey","table":"telecom_prefixes","schema":"public","definition":"CREATE UNIQUE INDEX telecom_prefixes_pkey ON public.telecom_prefixes USING btree (id)"},{"index":"telecom_prefixes_provider_prefix_unique","table":"telecom_prefixes","schema":"public","definition":"CREATE UNIQUE INDEX telecom_prefixes_provider_prefix_unique ON public.telecom_prefixes USING btree (provider_id, prefix)"},{"index":"telecom_providers_code_unique","table":"telecom_providers","schema":"public","definition":"CREATE UNIQUE INDEX telecom_providers_code_unique ON public.telecom_providers USING btree (lower(code))"},{"index":"telecom_providers_pkey","table":"telecom_providers","schema":"public","definition":"CREATE UNIQUE INDEX telecom_providers_pkey ON public.telecom_providers USING btree (id)"},{"index":"users_email_unique","table":"users","schema":"public","definition":"CREATE UNIQUE INDEX users_email_unique ON public.users USING btree (lower(email))"},{"index":"users_pkey","table":"users","schema":"public","definition":"CREATE UNIQUE INDEX users_pkey ON public.users USING btree (id)"}],"triggers":[{"event":"UPDATE","table":"customer_numbers","schema":"public","timing":"BEFORE","trigger":"customer_numbers_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"payment_methods","schema":"public","timing":"AFTER","trigger":"audit_payment_methods","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"DELETE","table":"payment_methods","schema":"public","timing":"AFTER","trigger":"audit_payment_methods","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"INSERT","table":"payment_methods","schema":"public","timing":"AFTER","trigger":"audit_payment_methods","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"UPDATE","table":"payment_methods","schema":"public","timing":"BEFORE","trigger":"payment_methods_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"payment_tasks","schema":"public","timing":"BEFORE","trigger":"payment_tasks_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"protection_plans","schema":"public","timing":"AFTER","trigger":"audit_protection_plans","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"DELETE","table":"protection_plans","schema":"public","timing":"AFTER","trigger":"audit_protection_plans","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"INSERT","table":"protection_plans","schema":"public","timing":"AFTER","trigger":"audit_protection_plans","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"UPDATE","table":"protection_plans","schema":"public","timing":"BEFORE","trigger":"protection_plan_provider_immutability","statement":"EXECUTE FUNCTION guard_used_plan_provider_change()"},{"event":"UPDATE","table":"protection_plans","schema":"public","timing":"BEFORE","trigger":"protection_plans_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"protection_requests","schema":"public","timing":"BEFORE","trigger":"protection_requests_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"protections","schema":"public","timing":"BEFORE","trigger":"protections_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"system_settings","schema":"public","timing":"BEFORE","trigger":"system_settings_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"INSERT","table":"task_settings","schema":"public","timing":"AFTER","trigger":"audit_task_settings","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"UPDATE","table":"task_settings","schema":"public","timing":"AFTER","trigger":"audit_task_settings","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"DELETE","table":"task_settings","schema":"public","timing":"AFTER","trigger":"audit_task_settings","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"UPDATE","table":"task_settings","schema":"public","timing":"BEFORE","trigger":"task_settings_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"telecom_prefixes","schema":"public","timing":"BEFORE","trigger":"telecom_prefixes_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"DELETE","table":"telecom_providers","schema":"public","timing":"AFTER","trigger":"audit_telecom_providers","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"UPDATE","table":"telecom_providers","schema":"public","timing":"AFTER","trigger":"audit_telecom_providers","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"INSERT","table":"telecom_providers","schema":"public","timing":"AFTER","trigger":"audit_telecom_providers","statement":"EXECUTE FUNCTION audit_configuration_change()"},{"event":"UPDATE","table":"telecom_providers","schema":"public","timing":"BEFORE","trigger":"telecom_providers_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"},{"event":"UPDATE","table":"users","schema":"public","timing":"BEFORE","trigger":"users_security_guard","statement":"EXECUTE FUNCTION guard_user_security_fields()"},{"event":"UPDATE","table":"users","schema":"public","timing":"BEFORE","trigger":"users_updated_at","statement":"EXECUTE FUNCTION set_updated_at()"}],"functions":[{"name":"add_customer_number","schema":"public","arguments":"p_phone_number text","definition":"CREATE OR REPLACE FUNCTION public.add_customer_number(p_phone_number text)
 RETURNS customer_numbers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'pg_temp'
AS $function$
declare
  v_row public.customer_numbers;
  v_normalized text;
  v_provider uuid;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  v_normalized := regexp_replace(trim(p_phone_number), '\s+', '', 'g');

  v_provider := public.detect_provider_for_number(v_normalized);

  if not exists (
    select 1 from public.telecom_providers
    where id = v_provider and is_active = true
  ) then
    raise exception 'PROVIDER_NOT_ACTIVE';
  end if;

  if exists (select 1 from public.customer_numbers where phone_number = v_normalized) then
    raise exception 'PHONE_NUMBER_ALREADY_EXISTS';
  end if;

  insert into public.customer_numbers(customer_id, provider_id, phone_number)
  values (auth.uid(), v_provider, v_normalized)
  returning * into v_row;

  return v_row;
end;
$function$
","return_type":"customer_numbers"},{"name":"admin_audit_logs","schema":"public","arguments":"p_search text, p_action_type text, p_from timestamp with time zone, p_to timestamp with time zone","definition":"CREATE OR REPLACE FUNCTION public.admin_audit_logs(p_search text DEFAULT NULL::text, p_action_type text DEFAULT NULL::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS SETOF audit_logs
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select a.* from public.audit_logs a
  where public.is_manager()
    and (p_action_type is null or a.action_type=trim(p_action_type))
    and (p_from is null or a.created_at>=p_from)
    and (p_to is null or a.created_at<=p_to)
    and (nullif(trim(p_search),'') is null
      or a.action_type ilike '%'||trim(p_search)||'%'
      or a.affected_table ilike '%'||trim(p_search)||'%'
      or a.affected_record_id::text ilike '%'||trim(p_search)||'%')
  order by a.created_at desc;
$function$
","return_type":"SETOF audit_logs"},{"name":"admin_create_notification","schema":"public","arguments":"p_customer_id uuid, p_title text, p_message text, p_notification_type text","definition":"CREATE OR REPLACE FUNCTION public.admin_create_notification(p_customer_id uuid, p_title text, p_message text, p_notification_type text)
 RETURNS notifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.notifications;
begin
  if not public.is_manager() then raise exception 'MANAGER_ONLY'; end if;
  if p_customer_id is not null and not exists(select 1 from public.users where id=p_customer_id) then
    raise exception 'CUSTOMER_NOT_FOUND';
  end if;
  if nullif(trim(p_title),'') is null then raise exception 'NOTIFICATION_TITLE_REQUIRED'; end if;
  if nullif(trim(p_message),'') is null then raise exception 'NOTIFICATION_MESSAGE_REQUIRED'; end if;
  insert into public.notifications(customer_id,title,message,notification_type)
  values(p_customer_id,trim(p_title),trim(p_message),trim(p_notification_type))
  returning * into v_row;
  return v_row;
end $function$
","return_type":"notifications"},{"name":"admin_create_payment_method","schema":"public","arguments":"p_name text, p_account_number text, p_account_owner_name text, p_payment_instructions text, p_is_active boolean","definition":"CREATE OR REPLACE FUNCTION public.admin_create_payment_method(p_name text, p_account_number text, p_account_owner_name text, p_payment_instructions text DEFAULT NULL::text, p_is_active boolean DEFAULT true)
 RETURNS payment_methods
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.payment_methods;
begin
  if not public.is_manager() then raise exception 'MANAGER_ONLY'; end if;
  insert into public.payment_methods(name,account_number,account_owner_name,payment_instructions,is_active)
  values(trim(p_name),trim(p_account_number),trim(p_account_owner_name),p_payment_instructions,p_is_active)
  returning * into v_row;
  return v_row;
end $function$
","return_type":"payment_methods"},{"name":"admin_create_protection_plan","schema":"public","arguments":"p_provider_id uuid, p_name text, p_price numeric, p_duration_days integer, p_is_active boolean, p_is_visible_to_customers boolean","definition":"CREATE OR REPLACE FUNCTION public.admin_create_protection_plan(p_provider_id uuid, p_name text, p_price numeric, p_duration_days integer, p_is_active boolean DEFAULT true, p_is_visible_to_customers boolean DEFAULT true)
 RETURNS protection_plans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.protection_plans;
begin
  if not public.is_manager() then raise exception 'MANAGER_ONLY'; end if;
  if not exists(select 1 from public.telecom_providers where id=p_provider_id)
    then raise exception 'PROVIDER_NOT_FOUND'; end if;
  insert into public.protection_plans(provider_id,name,price,protection_duration_days,is_active,is_visible_to_customers)
  values(p_provider_id,trim(p_name),p_price,p_duration_days,p_is_active,p_is_visible_to_customers)
  returning * into v_row;
  return v_row;
end $function$
","return_type":"protection_plans"},{"name":"admin_create_telecom_provider","schema":"public","arguments":"p_name text, p_code text, p_phone_length integer, p_prefixes text[], p_is_active boolean, p_is_visible_to_customers boolean, p_display_order integer","definition":"CREATE OR REPLACE FUNCTION public.admin_create_telecom_provider(p_name text, p_code text, p_phone_length integer, p_prefixes text[] DEFAULT '{}'::text[], p_is_active boolean DEFAULT true, p_is_visible_to_customers boolean DEFAULT true, p_display_order integer DEFAULT 0)
 RETURNS telecom_providers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'pg_temp'
AS $function$
declare
  v_provider public.telecom_providers;
  v_prefix text;
begin
  if not public.is_manager() then raise exception 'MANAGER_ONLY'; end if;
  if nullif(trim(p_name),'') is null then raise exception 'PROVIDER_NAME_REQUIRED'; end if;
  if nullif(trim(p_code),'') is null then raise exception 'PROVIDER_CODE_REQUIRED'; end if;
  if p_phone_length <= 0 then raise exception 'PHONE_LENGTH_INVALID'; end if;

  insert into public.telecom_providers(name,code,phone_length,is_active,is_visible_to_customers,display_order)
  values(trim(p_name),trim(p_code),p_phone_length,p_is_active,p_is_visible_to_customers,p_display_order)
  returning * into v_provider;

  foreach v_prefix in array coalesce(p_prefixes,'{}') loop
    if nullif(trim(v_prefix),'') is not null then
      insert into public.telecom_prefixes(provider_id,prefix)
      values(v_provider.id,trim(v_prefix));
    end if;
  end loop;

  return v_provider;
end;
$function$
","return_type":"telecom_providers"},{"name":"admin_customer_numbers","schema":"public","arguments":"p_search text, p_provider_id uuid, p_customer_id uuid","definition":"CREATE OR REPLACE FUNCTION public.admin_customer_numbers(p_search text DEFAULT NULL::text, p_provider_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF customer_numbers
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select n.* from public.customer_numbers n
  where public.is_manager()
    and (p_provider_id is null or n.provider_id=p_provider_id)
    and (p_customer_id is null or n.customer_id=p_customer_id)
    and (nullif(trim(p_search),'') is null or n.phone_number ilike '%'||trim(p_search)||'%')
  order by n.created_at desc;
$function$
","return_type":"SETOF customer_numbers"},{"name":"admin_customers","schema":"public","arguments":"p_search text","definition":"CREATE OR REPLACE FUNCTION public.admin_customers(p_search text DEFAULT NULL::text)
 RETURNS SETOF users
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select u.* from public.users u
  where public.is_manager()
    and (nullif(trim(p_search),'') is null
      or u.name ilike '%'||trim(p_search)||'%'
      or u.email ilike '%'||trim(p_search)||'%')
  order by u.created_at desc;
$function$
","return_type":"SETOF users"},{"name":"admin_delete_payment_method","schema":"public","arguments":"p_payment_method_id uuid","definition":"CREATE OR REPLACE FUNCTION public.admin_delete_payment_method(p_payment_method_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.is_manager() then raise exception 'MANAGER_ONLY'; end if;
  if exists(select 1 from public.protection_requests where payment_method_id=p_payment_method_id)
    then raise exception 'PAYMENT_METHOD_HAS_HISTORICAL_DATA_USE_DEACTIVATION'; end if;
  delete from public.payment_methods where id=p_payment_method_id;
  if not found then raise exception 'PAYMENT_METHOD_NOT_FOUND'; end if;
  return true;
end $function$
","return_type":"boolean"},{"name":"admin_delete_protection_plan","schema":"public","arguments":"p_plan_id uuid","definition":"CREATE OR REPLACE FUNCTION public.admin_delete_protection_plan(p_plan_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.is_manager() then raise exception 'MANAGER_ONLY'; end if;
  if exists(select 1 from public.protection_requests where plan_id=p_plan_id)
     or exists(select 1 from public.protections where plan_id=p_plan_id)
  then raise exception 'PLAN_HAS_HISTORICAL_DATA_USE_DEACTIVATION'; end if;
  delete from public.protection_plans where id=p_plan_id;
  if not found then raise exception 'PLAN_NOT_FOUND'; end if;
  return true;
end $function$
","return_type":"boolean"},{"name":"admin_delete_telecom_provider","schema":"public","arguments":"p_provider_id uuid","definition":"CREATE OR REPLACE FUNCTION public.admin_delete_telecom_provider(p_provider_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.is_manager() then raise exception 'MANAGER_ONLY'; end if;

  if exists(select 1 from public.customer_numbers where provider_id=p_provider_id)
     or exists(select 1 from public.protection_requests where provider_id=p_provider_id)
     or exists(select 1 from public.protections where provider_id=p_provider_id)
     or exists(select 1 from public.protection_plans where provider_id=p_provider_id)
     or exists(select 1 from public.task_settings where provider_id=p_provider_id)
  then
    raise exception 'PROVIDER_HAS_HISTORICAL_DATA_USE_DEACTIVATION';
  end if;

  delete from public.telecom_providers where id=p_provider_id;
  if not found then raise exception 'PROVIDER_NOT_FOUND'; end if;
  return true;
end $function$
","return_type":"boolean"},{"name":"admin_protection_requests","schema":"public","arguments":"p_status text, p_search text, p_provider_id uuid","definition":"CREATE OR REPLACE FUNCTION public.admin_protection_requests(p_status text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_provider_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF protection_requests
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.* from public.protection_requests r
  where public.is_manager()
    and (p_status is null or r.status::text=lower(trim(p_status)))
    and (p_provider_id is null or r.provider_id=p_provider_id)
    and (
      nullif(trim(p_search),'') is null
      or exists (
        select 1 from public.customer_numbers n
        join public.users u on u.id=n.customer_id
        where n.id=r.customer_number_id
          and (n.phone_number ilike '%'||trim(p_search)||'%' or u.name ilike '%'||trim(p_search)||'%' or u.email ilike '%'||trim(p_search)||'%')
      )
    )
  order by r.created_at desc;
$function$
","return_type":"SETOF protection_requests"},{"name":"admin_protections","schema":"public","arguments":"p_filter text, p_search text, p_provider_id uuid","definition":"CREATE OR REPLACE FUNCTION public.admin_protections(p_filter text DEFAULT 'all'::text, p_search text DEFAULT NULL::text, p_provider_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF protections
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p.* from public.protections p
  where public.is_manager()
    and (p_provider_id is null or p.provider_id=p_provider_id)
    and (
      nullif(trim(p_search),'') is null
      or exists (
        select 1 from public.customer_numbers n
        join public.users u on u.id=n.customer_id
        where n.id=p.customer_number_id
          and (n.phone_number ilike '%'||trim(p_search)||'%' or u.name ilike '%'||trim(p_search)||'%' or u.email ilike '%'||trim(p_search)||'%')
      )
    )
    and case lower(coalesce(p_filter,'all'))
      when 'all' then true
      when 'active' then public.protection_display_status(p.end_date) = 'active'
      when 'expired' then public.protection_display_status(p.end_date) = 'expired'
      when 'renewal' then public.protection_display_status(p.end_date) = 'renewal_needed'
      else false
    end
  order by p.end_date, p.created_at desc;
$function$
