","return_type":"cstring"},{"name":"get_my_protections","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.get_my_protections()
 RETURNS TABLE(id uuid, customer_id uuid, customer_number_id uuid, provider_id uuid, plan_id uuid, created_from_request_id uuid, protection_value numeric, protection_duration_days integer, start_date date, end_date date, status protection_status, display_status text, days_remaining integer, plan_name_snapshot text, provider_name_snapshot text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p.id,p.customer_id,p.customer_number_id,p.provider_id,p.plan_id,
         p.created_from_request_id,p.protection_value,p.protection_duration_days,
         p.start_date,p.end_date,p.status,
         public.protection_display_status(p.end_date) as display_status,
         greatest(p.end_date-current_date,0) as days_remaining,
         p.plan_name_snapshot,p.provider_name_snapshot,p.created_at,p.updated_at
  from public.protections p
  where p.customer_id=auth.uid()
  order by p.end_date desc,p.created_at desc;
$function$
","return_type":"TABLE(id uuid, customer_id uuid, customer_number_id uuid, provider_id uuid, plan_id uuid, created_from_request_id uuid, protection_value numeric, protection_duration_days integer, start_date date, end_date date, status protection_status, display_status text, days_remaining integer, plan_name_snapshot text, provider_name_snapshot text, created_at timestamp with time zone, updated_at timestamp with time zone)"},{"name":"guard_used_plan_provider_change","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.guard_used_plan_provider_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.provider_id is distinct from old.provider_id then
    if exists (select 1 from public.protection_requests where plan_id = old.id)
       or exists (select 1 from public.protections where plan_id = old.id) then
      raise exception 'USED_PLAN_PROVIDER_IMMUTABLE';
    end if;
  end if;
  return new;
end;
$function$
","return_type":"trigger"},{"name":"guard_user_security_fields","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.guard_user_security_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'pg_temp'
AS $function$
begin
  if auth.uid() is not null and not public.is_manager() then
    if new.role <> old.role then
      raise exception 'ROLE_CHANGE_FORBIDDEN';
    end if;
    if new.status <> old.status then
      raise exception 'ACCOUNT_STATUS_CHANGE_FORBIDDEN';
    end if;
  end if;

  if new.role <> old.role then
    raise exception 'ROLE_CHANGE_FORBIDDEN';
  end if;

  return new;
end;
$function$
","return_type":"trigger"},{"name":"handle_new_auth_user","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'pg_temp'
AS $function$
declare
  v_name text;
  v_email text;
begin
  v_name := nullif(trim(coalesce(new.raw_user_meta_data ->> 'name', '')), '');
  v_email := lower(trim(coalesce(new.email, '')));

  if v_name is null then
    raise exception 'NAME_REQUIRED';
  end if;

  if v_email = '' then
    raise exception 'EMAIL_REQUIRED';
  end if;

  insert into public.users(id, name, email, role, status)
  values (new.id, v_name, v_email, 'customer', 'active')
  on conflict (id) do nothing;

  return new;
end;
$function$
","return_type":"trigger"},{"name":"int2_dist","schema":"public","arguments":"smallint, smallint","definition":"CREATE OR REPLACE FUNCTION public.int2_dist(smallint, smallint)
