 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (
    select 1 from public.users
    where id = auth.uid() and role = 'manager' and status = 'active'
  );
$function$
","return_type":"boolean"},{"name":"is_payment_task_visible","schema":"public","arguments":"p_task_id uuid, p_on_date date","definition":"CREATE OR REPLACE FUNCTION public.is_payment_task_visible(p_task_id uuid, p_on_date date DEFAULT CURRENT_DATE)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (
    select 1
    from public.payment_tasks t
    join public.protections p on p.id = t.protection_id
    join public.task_settings s on s.provider_id = p.provider_id
    where t.id = p_task_id
      and (
        t.status in ('completed','cancelled')
        or p_on_date >= (t.due_date - s.days_visible_before_due)
      )
  );
$function$
","return_type":"boolean"},{"name":"mark_notification_read","schema":"public","arguments":"p_notification_id uuid","definition":"CREATE OR REPLACE FUNCTION public.mark_notification_read(p_notification_id uuid)
 RETURNS notifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'pg_temp'
AS $function$
declare
  v_notification public.notifications;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  update public.notifications
  set is_read = true,
      read_at = coalesce(read_at, now())
  where id = p_notification_id
    and customer_id = auth.uid()
  returning * into v_notification;

  if not found then
    raise exception 'NOTIFICATION_NOT_FOUND_OR_NOT_OWNED';
  end if;

  return v_notification;
end;
$function$
","return_type":"notifications"},{"name":"oid_dist","schema":"public","arguments":"oid, oid","definition":"CREATE OR REPLACE FUNCTION public.oid_dist(oid, oid)
 RETURNS oid
 LANGUAGE c
 IMMUTABLE PARALLEL SAFE STRICT
AS '$libdir/btree_gist', $function$oid_dist$function$
","return_type":"oid"},{"name":"process_protection_lifecycle","schema":"public","arguments":"","definition":"CREATE OR REPLACE FUNCTION public.process_protection_lifecycle()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer;
begin
  -- This operation is intended for the trusted maintenance/scheduler path.
  update public.protections
  set status = 'expired', updated_at = now()
  where status = 'active' and end_date < current_date;
  get diagnostics v_count = row_count;

  if v_count > 0 then
    perform public.write_audit_log(
      'process_protection_lifecycle', null, 'protections',
      jsonb_build_object('expired_count', v_count), null, null
    );
  end if;
  return v_count;
end;
