","return_type":"integer"},{"name":"protection_display_status","schema":"public","arguments":"p_end_date date","definition":"CREATE OR REPLACE FUNCTION public.protection_display_status(p_end_date date)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_threshold integer;
begin
  select renewal_threshold_days into v_threshold
  from public.system_settings where id = true;
  v_threshold := coalesce(v_threshold, 30);

  if p_end_date < current_date then return 'expired'; end if;
  if p_end_date <= current_date + v_threshold then return 'renewal_needed'; end if;
  return 'active';
end;
