","return_type":"integer"},{"name":"refresh_task_status","schema":"public","arguments":"p_task_id uuid","definition":"CREATE OR REPLACE FUNCTION public.refresh_task_status(p_task_id uuid)
 RETURNS task_status
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp', 'pg_temp'
AS $function$
declare
  v_task public.payment_tasks;
  v_status public.task_status;
begin
  select * into v_task from public.payment_tasks where id = p_task_id;
  if not found then raise exception 'TASK_NOT_FOUND'; end if;

  if not public.is_manager() then
    raise exception 'MANAGER_REQUIRED';
  end if;

  if v_task.status in ('completed','cancelled') then
    return v_task.status;
  end if;

  v_status := case
    when v_task.due_date < current_date then 'overdue'
    when v_task.due_date = current_date then 'due'
    else 'upcoming'
  end;

  update public.payment_tasks
  set status = v_status
  where id = p_task_id;

  return v_status;
end;
